# cc-P34 WRITES D:\ShatteredLegacy\server\customizations\ClusterFWinterDecorLayout.cs from placement.json (checked by
# validate.py first: it refuses to write while any row fails) and the spawner tiles of protected.py. Re-run after any
# change to placement.json, then build. The server reads only the generated file.
import json, subprocess, sys
r = subprocess.run([sys.executable, 'validate.py'], capture_output=True, text=True)
if r.returncode:
    sys.exit('validate.py fails; not writing:\n' + r.stdout[-2000:])
exec(open('protected.py').read().split("if __name__")[0])
rows = json.load(open('placement.json'))
HUE = {0x8E2: 0x481, 0x8E0: 0x481, 0x8E6: 0x481, 0x8E5: 0x481, 0x8E3: 0x481}   # pinned SnowPileDeco: Hue = 0x481
def cs(s): return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
out = []
out.append('// GENERATED by shard-migration notes/cc-P34-tools/gen_layout.py from placement.json. Do not edit by hand:')
out.append('// change placement.json, run validate.py (the map checks), then gen_layout.py.')
out.append('//')
out.append('// cc-P34 (F-22): the winter decor for New Haven, one row per item, all on Trammel. Every row was checked against')
out.append('// the server\'s own map files: surface z, nothing impassable in the way, not a road (outside the square and the')
out.append('// pier), not a door, door swing, NPC post, spawner tile, the arrival tile or the Reset Stone; wall art only in front')
out.append('// of a north or west wall (the faces the client shows). The table with a reason per row is in the cc-P34 notes.')
out.append('')
out.append('namespace Server;')
out.append('')
out.append('public static class ClusterFWinterDecorLayout')
out.append('{')
out.append('    public sealed record Row(string Key, string Area, int X, int Y, int Z, int ItemId, string Name, int Hue, string Facing, string Layer);')
out.append('')
out.append('    public static readonly Row[] Rows =')
out.append('    {')
for r in rows:
    out.append('        new(%s, %s, %d, %d, %d, 0x%04X, %s, 0x%03X, %s, %s),' % (cs(r['key']), cs(r['area']), r['x'], r['y'], r['z'], r['itemId'], cs(r['name']),
                                                                          HUE.get(r['itemId'], 0), cs(r['facing']), cs(r['layer'])))
out.append('    };')
out.append('')
out.append('    // Every pinned Distribution/Data/Spawns entry on Trammel inside x3400-3560, y2460-2660, and our healer spawner.')
out.append('    // No row may sit on one (the test reads this list; a spawner placed later is not in it).')
out.append('    public static readonly (int X, int Y)[] SpawnerTiles =')
out.append('    {')
sp = sorted({k for k, v in P.items() if any(w.startswith('spawner') for w in v)})
for i in range(0, len(sp), 8):
    out.append('        ' + ' '.join('(%d, %d),' % t for t in sp[i:i + 8]))
out.append('    };')
out.append('}')
open(r'D:/ShatteredLegacy/server/customizations/ClusterFWinterDecorLayout.cs', 'w', encoding='ascii', newline='\n').write('\n'.join(out) + '\n')
print('wrote', len(rows), 'rows,', len(sp), 'spawner tiles')
